  return {
    baseLanes: renderLanes,
    cachePool: getSuspendedCache(),
    transitions: null,
  };
}

function updateSuspenseOffscreenState(
  prevOffscreenState: OffscreenState,
  renderLanes: Lanes,
): OffscreenState {
  let cachePool: SpawnedCachePool | null = null;
